use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder\SmtpOutboundConfigSenderEmailAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigSenderEmailAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SmtpOutboundConfigSenderEmailAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getSenderEmail returns null on a freshly created holder.
     */
    public function testSenderEmailNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigSenderEmailAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isSenderEmailAssigned());
        $this->assertNull($holder->getSenderEmail());
    }
}
class ImplWithSmtpOutboundConfigSenderEmailAttributeHolderUnitTest
{
    use SmtpOutboundConfigSenderEmailAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedSenderEmailRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultSenderEmail();
    }
}
